list_tax_rules.code:
import {taxRules} from 'webcommander-sdk';

const response = await taxRules.listTaxRules(client, {limit: 20});
for (const taxRule of response.map.tax_rules) {
    console.log(taxRule.id, taxRule.name, taxRule.default);
}
console.log(response.map.pagination.total);

head_tax_rules.code:
import {taxRules} from 'webcommander-sdk';

const response = await taxRules.headTaxRules(client);
console.log(response.statusCode);

create_tax_rule.code:
import {taxRules} from 'webcommander-sdk';

const response = await taxRules.createTaxRule(client, {
    tax_rule: {name: 'Reduced rate', description: 'Rule for reduced-rate goods'},
});
console.log(response.map.tax_rule.id);

get_tax_rule.code:
import {taxRules} from 'webcommander-sdk';

const response = await taxRules.getTaxRule(client, 7);
const taxRule = response.map.tax_rule;
console.log(taxRule.name, taxRule.code.name);
for (const zone of taxRule.zones) {
    console.log(zone.id, zone.name);
}

